Q: How to minify php page html output? A: <h1>class Minifier</h1>
<p><em><sup>I know this doesn't answer the main question about output. It's more of  an &quot;how to minify&quot; reply. But I think many of the above answers are either incomplete or tries to explain the minifying process. So I guess my contribution will be accepted.</sup></em></p>
<p>Based on ideas from <a href="https://datayze.com/howto/minify-javascript-with-php" rel="nofollow noreferrer">an article by datayze</a>, I made the following class, which is what I use in my projects. I've added more to it than what is said in the article. My current version handles regex, css calc() amd template literals better than the datayze version.</p>
<h2>How to use</h2>
<p>The Minifier has a constructor and 3 main functions.</p>
<ol>
<li><p>minifyHTML(&lt;html&gt;)<br />
Takes any html text sting (including script tags and css tags) and returns a minified version of them all.</p>
</li>
<li><p>minifyJS(&lt;javascript&gt;)<br />
Takes a string containing javascript and returns a minified version without modified identifiers.</p>
</li>
<li><p>minifyCSS(&lt;css&gt;)<br />
Takes a css block as a string and returns a minified version.</p>
</li>
</ol>
<p><strong>Example</strong>:</p>
<p>Here's an example of how to use it. The two important lines are marked as such.</p>
<pre><code>&lt;?php
function minifyHtmlFile($filename) {
    // Read the file ...
    $html = file_get_contents($filename);
    // ... and its size.
    $old_size = strlen($html);
    // Create a minifier
    $minifier = new Minifier(); // ← important
    // Strip all unnecessary blanks, comments and line breakes
    $minified = $minifier-&gt;minifyHTML($html); // ← important
    // Get the new size
    $new_size = strlen($minified);
    // Save the file
    file_put_contents($filename,$minified);
    // Return a report
    return ['file'=&gt;$filename,'compression'=&gt;round(100*(1-$new_size/$old_size)).'%'];
}
?&gt;
</code></pre>
<p>You don't need to create new minifiers every time. The same <code>$minifier</code> may be used any number of times.</p>
<h2>The file Minifier.php</h2>
<p>Here it is. Copy and use as you like.</p>
<pre><code>&lt;?php
/**
 *  Minifier based on https://datayze.com/howto/minify-javascript-with-php.
 *  But with several improvements by Johan Avén.
 *  Curren version: 2025-10-19
 */

class Minifier {
    private $minificationStore;
    private $singleQuoteSequenceFinder;
    private $doubleQuoteSequenceFinder;
    private $blockCommentFinder;
    private $lineCommentFinder;
    private $jsRegexSequenceFinder;
    private $cssCalcFinder;
    private $templateLiteralSequenceFinder;

    const VERSION = '2025-10-19 (c) Johan Avén';

    function __construct() {
        $this-&gt;minificationStore = array();
        $this-&gt;singleQuoteSequenceFinder = new QuoteSequenceFinder('\'');
        $this-&gt;doubleQuoteSequenceFinder = new QuoteSequenceFinder('&quot;');
        $this-&gt;blockCommentFinder = new StringSequenceFinder('/*', '*/');
        $this-&gt;lineCommentFinder = new StringSequenceFinder('//', &quot;\n&quot;);
        $this-&gt;jsRegexSequenceFinder = new JSRegexSequenceFinder();
        $this-&gt;cssCalcFinder = new CssCalcFinder();
        $this-&gt;templateLiteralSequenceFinder = new QuoteSequenceFinder('`');
    }   


    function getNextMinificationPlaceholder(){
        return '&lt;-!!-' . sizeof($this-&gt;minificationStore) . '-!!-&gt;';
    }


    function getNextSpecialSequence($string, $sequences){
    // $special_idx is an array of the nearest index for all special characters
        $special_idx = array();
        foreach ($sequences as $finder){
            $finder-&gt;findFirstValue($string);
            if ($finder-&gt;isValid()){
                $special_idx[$finder-&gt;start_idx] = $finder;
            }
        }
        // if none found, return
        if (count($special_idx) == 0){return false;}
        // get first occuring item
        asort($special_idx);
        return $special_idx[min(array_keys($special_idx))];
    }


    private function resetMinificationStore(){
        $this-&gt;minificationStore = array();
    }

    function minifyCSS($css, $reset=true){
        if ($reset) $this-&gt;resetMinificationStore();
        $css_special_chars = array(
            $this-&gt;blockCommentFinder, // CSS Comment
            $this-&gt;singleQuoteSequenceFinder, // single quote escape, e.g. :before{ content: '-';}
            $this-&gt;doubleQuoteSequenceFinder, // double quote
            $this-&gt;cssCalcFinder); // Ex. calc(50% - 400px) 
        // pull out everything that needs to be pulled out and saved
        while ($sequence = $this-&gt;getNextSpecialSequence($css, $css_special_chars)){
            switch ($sequence-&gt;type){
            case '/*': // remove comments
                $css = substr($css, 0, $sequence-&gt;start_idx) . substr($css, $sequence-&gt;end_idx);
            break;
            default: // strings that need to be preservered
                $placeholder = $this-&gt;getNextMinificationPlaceholder();
                $this-&gt;minificationStore[$placeholder] = substr($css, $sequence-&gt;start_idx, $sequence-&gt;end_idx - $sequence-&gt;start_idx);
                $css = substr($css, 0, $sequence-&gt;start_idx) . $placeholder . substr($css, $sequence-&gt;end_idx);
            }
        }
        // minimize the string
        $css = preg_replace('/\s{2,}/s', ' ', $css);
        $css = preg_replace('/\s*([:;{}])\s*/', '$1', $css);
        $css = preg_replace('/;}/', '}', $css);
        // put back the preserved strings
        foreach($this-&gt;minificationStore as $placeholder =&gt; $original){
            $css = str_replace($placeholder, $original, $css);
        }
        return trim($css);
    }

    function minifyHTML($html, $reset=true){
        if ($reset) $this-&gt;resetMinificationStore();
        $html_special_chars = array(
            new RegexSequenceFinder('javascript', &quot;/&lt;\s*script(?:[^&gt;]*)&gt;(.*?)&lt;\s*\/script\s*&gt;/si&quot;), // javascript, can have type attribute
            new RegexSequenceFinder('css', &quot;/&lt;\s*style(?:[^&gt;]*)&gt;(.*?)&lt;\s*\/style\s*&gt;/si&quot;), // css, can have type/media attribute
            new RegexSequenceFinder('pre', &quot;/&lt;\s*pre(?:[^&gt;]*)&gt;(.*?)&lt;\s*\/pre\s*&gt;/si&quot;) // pre
        );
//      $html = $this-&gt;preserveEmeddedPHP($html);  // I didn't include this function
        // pull out everything that needs to be pulled out and saved
        while ($sequence = $this-&gt;getNextSpecialSequence($html, $html_special_chars)){
            $placeholder = $this-&gt;getNextMinificationPlaceholder();
            $quote = substr($html, $sequence-&gt;start_idx, $sequence-&gt;end_idx - $sequence-&gt;start_idx);
            // subsequence (css/javascript/pre) needs special handeling, tags can still be minimized using minifyPHP
            $sub_start = $sequence-&gt;sub_start_idx- $sequence-&gt;start_idx;
            $sub_end = $sub_start + strlen($sequence-&gt;sub_match);
            switch ($sequence-&gt;type){
            case 'javascript':
                $quote = $this-&gt;minifyHTML(substr($quote, 0, $sub_start),false) . $this-&gt;minifyJS($sequence-&gt;sub_match, false) . $this-&gt;minifyHTML(substr($quote, $sub_end),false);
            break;
            case 'css':
                $quote = $this-&gt;minifyHTML(substr($quote, 0, $sub_start),false) . $this-&gt;minifyCSS($sequence-&gt;sub_match, false) . $this-&gt;minifyHTML(substr($quote, $sub_end),false);
            break;
            default: // strings that need to be preservered, e.g. between &lt;pre&gt; tags
                $quote = $this-&gt;minifyHTML(substr($quote, 0, $sub_start),false) . $sequence-&gt;sub_match . $this-&gt;minifyHTML(substr($quote, $sub_end),false);
            }
            $this-&gt;minificationStore[$placeholder] = $quote;
            $html = substr($html, 0, $sequence-&gt;start_idx) . $placeholder . substr($html, $sequence-&gt;end_idx);
        }
        // condense white space
        $html = preg_replace(
            array('/\s+/', '/&lt;\s+/', '/\s+&gt;/'),
            array(' ', '&lt;', '&gt;'),
            $html);
        // remove comments
        $html = preg_replace('/&lt;!--([^-](?!(-&gt;)))*--&gt;/', '', $html);
        // remove space after block elements
        $html = preg_replace('/(&lt;\/(?:h\d|p|ul|li|div)&gt;)(\s+)(&lt;)/', '$1$3', $html);
        // remove spaces before block elements
        $html = preg_replace('/(&gt;)(\s+)(&lt;(?:h\d|p|ul|li|div)(?:\s+[^&lt;]*)?&gt;)/', '$1$3', $html);
        // put back the preserved strings
        foreach($this-&gt;minificationStore as $placeholder =&gt; $original){
            $html = str_replace($placeholder, $original, $html);
        }
        return trim($html);
    }


    function minifyJS($javascript, $reset=true){
        if (is_null($javascript)) return NULL;
        if ($reset) $this-&gt;resetMinificationStore();
        $java_special_chars = array(
            $this-&gt;blockCommentFinder,
            $this-&gt;lineCommentFinder,
            $this-&gt;singleQuoteSequenceFinder,
            $this-&gt;doubleQuoteSequenceFinder,
            $this-&gt;templateLiteralSequenceFinder,
            $this-&gt;jsRegexSequenceFinder
        );
        $counter = 0;
        // pull out everything that needs to be pulled out and saved
        while ($sequence = $this-&gt;getNextSpecialSequence($javascript, $java_special_chars)){
            switch ($sequence-&gt;type){
            case '/*':
            case '//':// remove comments
                $javascript = substr($javascript, 0, $sequence-&gt;start_idx) . substr($javascript, $sequence-&gt;end_idx);
            break;
            default: // quoted strings or regex that need to be preservered
                $start_idx = $sequence-&gt;start_idx;
                $end_idx = $sequence-&gt;end_idx ?? strlen($javascript);
                $placeholder = $this-&gt;getNextMinificationPlaceholder();
                $this-&gt;minificationStore[$placeholder] =substr($javascript, $start_idx, $end_idx - $start_idx);
                $javascript = substr($javascript, 0, $start_idx) . $placeholder . substr($javascript, $end_idx);
            }
        }
        // special case where the + indicates treating variable as numeric, e.g. a = b + +c
        $javascript = preg_replace('/([-\+])\s+\+([^\s;]*)/', '$1 (+$2)', $javascript);
        // condense spaces
        $javascript = preg_replace(&quot;/\s*\n\s*/&quot;, &quot;\n&quot;, $javascript); // spaces around newlines
        $javascript = preg_replace(&quot;/[\s\t]+/&quot;, ' ', $javascript); // \h+ horizontal white space
        // remove unnecessary horizontal spaces around non variables (alphanumerics, underscore, dollar sign)
        $javascript = preg_replace(&quot;/[ \t]([^A-Za-z0-9\_\$])/&quot;, '$1', $javascript);
        $javascript = preg_replace(&quot;/([^A-Za-z0-9\_\$])[ \t]/&quot;, '$1', $javascript);
        // remove unnecessary spaces around brackets and parentheses
        $javascript = preg_replace(&quot;/\s?([\(\[{])\s?/&quot;, '$1', $javascript);
        $javascript = preg_replace(&quot;/\s([\)\]}])/&quot;, '$1', $javascript);
        // remove unnecessary spaces around operators that don't need any spaces (specifically newlines)
        $javascript = preg_replace(&quot;/\s?([\.=:\-+,])\s?/&quot;, '$1', $javascript);
        // unnecessary characters
        $javascript = preg_replace(&quot;/;\n/&quot;, &quot;;&quot;, $javascript); // semicolon before newline
        $javascript = preg_replace('/;}/', '}', $javascript); // semicolon before end bracket       
        // put back the preserved strings
        foreach($this-&gt;minificationStore as $placeholder =&gt; $original){
            $javascript = str_replace($placeholder, $original, $javascript);
        }
        return trim($javascript);
    }

} // end of class Minifyer



abstract class MinificationSequenceFinder
{
    public $start_idx;
    public $end_idx;
    public $type;

    abstract protected function findFirstValue($string);
    public function isValid(){
        return $this-&gt;start_idx !== false;
    }
    protected function reset() {
        $this-&gt;start_idx = false;
        $this-&gt;end_idx = false;
    }
}




class StringSequenceFinder extends MinificationSequenceFinder
{
    protected $start_delimiter;
    protected $end_delimiter;
    function __construct($start_delimiter, $end_delimiter){
        $this-&gt;type = $start_delimiter;
        $this-&gt;start_delimiter = $start_delimiter;
        $this-&gt;end_delimiter = $end_delimiter;
    }
    public function findFirstValue($string){
        $this-&gt;reset();
        $this-&gt;start_idx = strpos($string, $this-&gt;start_delimiter);
        if ($this-&gt;isValid()){
            $this-&gt;end_idx = strpos($string, $this-&gt;end_delimiter, $this-&gt;start_idx+1);
            // sanity check for non well formed lines
            $this-&gt;end_idx = ($this-&gt;end_idx === false ? strlen($string) : $this-&gt;end_idx + strlen($this-&gt;end_delimiter));
        }
    }
}




class QuoteSequenceFinder extends MinificationSequenceFinder {
    function __construct($type){
        $this-&gt;type = $type;
    }
    public function findFirstValue($string){
        $this-&gt;reset();
        $this-&gt;start_idx = strpos($string, $this-&gt;type);
        if ($this-&gt;isValid()){
            // look for first non escaped endquote
            $this-&gt;end_idx = $this-&gt;start_idx+1;
                while ($this-&gt;end_idx &lt; strlen($string)){
                // find number of escapes before endquote
                if (preg_match('/(\\\\*)(' . preg_quote($this-&gt;type) . ')/', $string, $match, PREG_OFFSET_CAPTURE, $this-&gt;end_idx)){
                    $this-&gt;end_idx = $match[2][1] + 1;
                    // if odd number of escapes before endquote, endquote is escaped. Keep going
                    if (!isset($match[1][0]) || strlen($match[1][0]) % 2 == 0){
                        return;
                    }
                }else{
                    // no match, not well formed
                    $this-&gt;end_idx = strlen($string);
                    return;
                }
            }
        }
    }
}




// ********************************************************************************************************************************** JS



class JSRegexSequenceFinder extends MinificationSequenceFinder
{
    function __construct(){
        $this-&gt;type = 'regex';
    }
    /* check to make sure this isn't the start of a comment or a division  */
    public function findPossibleStart($string, $idx = 0){
        $start_idx = strpos($string, '/', $idx);
        if ($start_idx === false){
            return false;
        }
        if (substr($string, $start_idx, 2) === '//' ||
            substr($string, $start_idx, 2) === '/*'){
            return $this-&gt;findPossibleStart($string, $start_idx + 1);
        }
        $tmp = $start_idx - 1;
        // get first nonspace previous char
        while ($tmp &gt; 0 &amp;&amp; ctype_space(substr($string, $tmp, 1))) $tmp--;
        if ($tmp &gt; 0){
            $char = substr($string, $tmp, 1);
            // if char or number: then this is division, get further
            if (is_numeric($char) || ctype_alpha($char) || $char == ')' || $char == ']'){
                return $this-&gt;findPossibleStart($string, $start_idx + 1);
            }
        }
        return $start_idx;
    }

    public function findFirstValue($string){
        $this-&gt;reset();
        $this-&gt;start_idx = $this-&gt;findPossibleStart($string);
        if ($this-&gt;start_idx === false){
            return;
        }
        // position of first newline after pattern
        $nl = strpos($string, &quot;\n&quot;, $this-&gt;start_idx);
        // look for first non escaped endquote
        $end_idx = $this-&gt;start_idx+1;
        while ($end_idx &lt; strlen($string) // if there's still room to explore in the string
        &amp;&amp; ($nl === false || $end_idx &lt; $nl)) // and we're not at a newline yet
        {
            // find number of escapes before endquote
            if (preg_match('/(\\\\*)(\/)/', $string, $match, PREG_OFFSET_CAPTURE, $end_idx)){
                $end_idx = $match[2][1] + 1;
                // if odd number of escapes before endquote, endquote is escaped. Keep going
                if (!isset($match[1][0]) || strlen($match[1][0]) % 2 == 0){
                    if ($nl !== false &amp;&amp; $end_idx &gt; $nl){return false;}
                    $this-&gt;end_idx = $end_idx;
                    return;
                }
            // no match, not well formed
            } else{
                $this-&gt;start_idx = false;
                return;
            }
        }
    }
}   // end of class JSRegexSequenceFinder


// ************************************************************************************************************ HTML


class RegexSequenceFinder extends MinificationSequenceFinder
{
    protected $regex;
    public $sub_match;
    public $sub_start_idx;
    public $start_idx = false;
    public $full_match;
    public $end_idx;

    function __construct($type, $regex){
        $this-&gt;type = $type;
        $this-&gt;regex = $regex;
    }
    public function findFirstValue($string){
        $this-&gt;reset();
        preg_match($this-&gt;regex, $string, $matches, PREG_OFFSET_CAPTURE);
        if (count($matches) == 0){
            $this-&gt;start_idx = false;
            return false;
        }
        // full match
        $this-&gt;full_match = $matches[0][0];
        $this-&gt;start_idx = $matches[0][1];
        if (count($matches) &gt; 1){
            // substart
            $this-&gt;sub_match = $matches[1][0];
            $this-&gt;sub_start_idx = $matches[1][1];
        }
        $this-&gt;end_idx = $this-&gt;start_idx + strlen($this-&gt;full_match);
    }
}



// ************************************************************************************************************ CSS calc()


class CssCalcFinder extends MinificationSequenceFinder
{
    public $full_match = false;
    public function __construct() {
        $this-&gt;type = 'css_calc';
    }
    public function findFirstValue($string)
    {
        $this-&gt;reset();
        if (!preg_match('/calc\s*\(/i', $string, $m, PREG_OFFSET_CAPTURE)) {
            return false;
        }
        $start = $m[0][1];
        $offset = $start + strlen($m[0][0]) - 1; // at &quot;(&quot;
        $depth = 0;
        $len = strlen($string);
        for ($i = $offset; $i &lt; $len; $i++) {
            $char = $string[$i];
            if ($char === '(') {
                $depth++;
            }
            elseif ($char === ')') {
                $depth--;
                if ($depth === 0) {
                    $full_match = substr(
                        $string,
                        $start,
                        $i - $start + 1
                    );
                    // only protect calc() with spaced operators
                    if (!preg_match('/\s[+\-]\s/', $full_match)) {
                        return false;
                    }
                    $this-&gt;full_match = $full_match;
                    $this-&gt;start_idx = $start;
                    $this-&gt;end_idx = $i + 1;
                    return true;
                }
            }
        }
        return false;
    }
}
</code></pre>

